import { transSort } from './transSort';
import { RangeMan } from '@boss/h-table';
import { Operation, RemoveRowOperation } from '@bzl/sheet-js';

export const transRemoveRow = (
  leftOp: RemoveRowOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): Operation[] => {
  switch (rightOp.type) {
    case 'insert-row':
      // 不相交 不影响 （上边）
      if (leftOp.at + leftOp.count <= rightOp.at) {
        return [leftOp];
      }
      // 不相交 不影响（下边）
      if (leftOp.at > rightOp.at) {
        return [
          {
            ...leftOp,
            at: leftOp.at + rightOp.count,
          },
        ];
      }
      // 相交
      return [
        {
          ...leftOp,
          at: Math.min(rightOp.at, leftOp.at),
          count: leftOp.count + rightOp.count,
        },
      ];

    case 'remove-row': {
      if (leftOp.at + leftOp.count <= rightOp.at) {
        return [leftOp];
      }
      if (rightOp.at + rightOp.count <= leftOp.at) {
        return [
          {
            ...leftOp,
            at: Math.max(leftOp.at - rightOp.count, 0),
          },
        ];
      }
      const at = Math.min(leftOp.at, rightOp.at);
      const endAt = Math.max(rightOp.at + rightOp.count, leftOp.at + leftOp.count);
      return [
        {
          ...leftOp,
          at: Math.min(leftOp.at, rightOp.at),
          count: endAt - at,
        },
      ];
    }
    case 'sort': {
      const removeRange = [0, leftOp.at, Infinity, leftOp.at + leftOp.count - 1];
      const { before, after, range, sortBy } = rightOp;
      const effectRange = sortBy === 'sheet' ? [0, range[1], Infinity, range[3]] : range;
      if (
        RangeMan.isFullOverlapping(removeRange, effectRange) ||
        !RangeMan.isOverlapping(removeRange, effectRange)
      ) {
        return [leftOp];
      }
      if (sortBy === 'range') {
        // 先恢复重排，在进行整行删除，再进行重排
        const restoreSortOp = {
          ...rightOp,
          after: rightOp.before,
          before: rightOp.after,
        };

        // 将 sort 基于 leftOp 进行转换
        const [resortOp] = transSort(rightOp, leftOp);

        return [restoreSortOp, leftOp, resortOp];
      }
      // 相交，需要进行 散列
      const newOps: RemoveRowOperation[] = [];
      for (let r = leftOp.at; r < leftOp.at + leftOp.count; r++) {
        const exit = after.findIndex((i) => i === r);
        const newR = exit === -1 ? r : before[exit];
        const lastOp = newOps.length > 0 ? newOps[newOps.length - 1] : null;
        const canMerge = lastOp?.at === newR - 1;
        if (canMerge) {
          lastOp.count += 1;
        } else {
          newOps.push({
            ...leftOp,
            at: newR,
            count: 1,
          });
        }
      }
      return newOps;
    }
    default:
      return [leftOp];
  }
};
