import { Operation, InsertRowOperation } from '@bzl/sheet-js';

export const transInsertRow = (
  leftOp: InsertRowOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): InsertRowOperation[] => {
  switch (rightOp.type) {
    case 'insert-row':
      if (rightOp.at > leftOp.at) {
        return [leftOp];
      }
      if (rightOp.at === leftOp.at && side === 'left') {
        return [leftOp];
      }

      return [
        {
          ...leftOp,
          at: leftOp.at + rightOp.count,
        },
      ];
    case 'remove-row': {
      if (leftOp.at < rightOp.at) {
        return [leftOp];
      }
      if (leftOp.at >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: Math.max(leftOp.at - rightOp.count, 0),
          },
        ];
      }
      return [];
    }
    default:
      return [leftOp];
  }
};
