import { BaseSheet, Operation, Sheet, Transforms } from '@bzl/sheet-js';
import { xTransformMxN } from './xTransform/xTransformMxN';

export const SheetOTType = {
  name: 'sheet-ot-type',
  create: (initData: Sheet) => {
    initData = initData ?? {
      data: { rows: [], cols: [] },
      config: {},
    };
    initData.data = initData.data ?? { rows: [], cols: [] };
    initData.config = initData.config ?? {};
    // JSON.stringify(initData);
    return initData;
  },
  apply: (snapshot: Sheet, ops: Operation[] | Operation): BaseSheet => {
    // const sheetIns = SheetOTType.createSheetInstance(snapshot);
    // SheetOTType.normalize(ops).forEach((op) => sheetIns.apply(op));
    // return {
    //   data: sheetIns.data ?? { rows: [], cols: [] },
    //   config: sheetIns.config ?? {},
    // } as BaseSheet;
    return SheetOTType.normalize(ops).reduce((doc, op) => {
      Transforms.transform(doc, op);
      return doc;
    }, SheetOTType.create(snapshot));
  },
  transform: (leftOps: Operation[], rightOps: Operation[], side: 'right' | 'left') => {
    const [leftRes] = xTransformMxN(leftOps, rightOps, side);
    return leftRes;
  },
  xTransformMxN: (leftOps: Operation[], rightOps: Operation[], side: 'right' | 'left') => {
    return xTransformMxN(leftOps, rightOps, side);
  },
  normalize(op: Operation | Operation[]): Operation[] {
    const ops = Array.isArray(op) ? op : [op];
    return ops.map((op) => {
      if ('range' in op) {
        // Infinity 会被 JSON.stringify 序列化成 null，因此需要在这里进行 normalize
        return {
          ...op,
          range: op.range?.map((n) => (n === null || Number.isNaN(n) ? Infinity : n)),
        };
      }
      return op;
    });
  },
  transformX: (leftOps: Operation[], rightOps: Operation[]) => {
    return xTransformMxN(leftOps, rightOps, 'left');
  },
  // createSheetInstance: (baseSheet: Omit<BaseSheet, 'apply'>): Sheet => {
  //   return withFormula(
  //     createBaseSheet(baseSheet.data ?? { rows: [], cols: [] }, baseSheet.config ?? {}) as Sheet,
  //   );
  // },
  // 在 尝试回滚的时候调用，暂时不支持尝试回滚，只支持强制回滚（会将本地 pendingOps 抹掉）
  // invert: ()
  // 组合 op
  // compose
};
