import { Operation, RemoveColOperation } from '@bzl/sheet-js';

export const transRemoveCol = (
  leftOp: RemoveColOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): RemoveColOperation[] => {
  switch (rightOp.type) {
    case 'insert-col':
      if (leftOp.at + leftOp.count <= rightOp.at) {
        return [leftOp];
      }
      if (rightOp.at <= leftOp.at) {
        return [
          {
            ...leftOp,
            at: leftOp.at + rightOp.count,
          },
        ];
      }
      // 将 "insert-col" 的区域合并
      return [
        {
          ...leftOp,
          count: Math.max(rightOp.at + rightOp.count - leftOp.at, leftOp.count),
        },
      ];
    case 'remove-col': {
      if (leftOp.at + leftOp.count <= rightOp.at) {
        return [leftOp];
      }
      // at 位置偏移
      if (rightOp.at + rightOp.count <= leftOp.at) {
        return [
          {
            ...leftOp,
            at: Math.max(leftOp.at - rightOp.count, 0),
          },
        ];
      }
      // 合并两个 "remove-col" 区域
      const at = Math.min(leftOp.at, rightOp.at);
      const endAt = Math.max(rightOp.at + rightOp.count, leftOp.at + leftOp.count);
      return [
        {
          ...leftOp,
          at: Math.min(leftOp.at, rightOp.at),
          count: endAt - at,
        },
      ];
    }
    default:
      return [leftOp];
  }
};
