import {
  ConfigUpdate,
  Operation,
  DeleteImageOperation,
  InsertImageOperation,
  UpdateImageOperation,
  SetScaleOperation,
  SetSelectionOperation,
  RemoveFilterOperation,
  UpdateFreezeOperation,
  RemoveViewOperation,
} from '@bzl/sheet-js';
import OT from './OT';

export const doTransform = (
  leftOp: Operation,
  rightOp: Operation,
  side: 'left' | 'right',
): Operation[] => {
  switch (leftOp.type) {
    case 'insert-col':
      return OT.transInsertCol(leftOp, rightOp, side);
    case 'remove-col':
      return OT.transRemoveCol(leftOp, rightOp, side);
    case 'insert-row':
      return OT.transInsertRow(leftOp, rightOp, side);
    case 'remove-row':
      return OT.transRemoveRow(leftOp, rightOp, side);
    case 'update-merge': {
      return OT.transMergeCell(leftOp, rightOp, side);
    }
    case 'update-cell':
      return OT.transUpdateCell(leftOp, rightOp, side);
    case 'fill-range':
      return OT.transFillRange(leftOp, rightOp, side);
    case 'scatter-range': {
      return OT.transScatterRange(leftOp, rightOp, side);
    }
    case 'sort': {
      return OT.transSort(leftOp, rightOp, side);
    }
    case 'update-dimension': {
      return OT.transUpdateDimension(leftOp, rightOp, side);
    }
    case 'scatter-dimension': {
      return OT.transScatterDimension(leftOp, rightOp, side);
    }
    case 'insert-annotation':
    case 'delete-annotation': {
      return OT.transAnnotation(leftOp, rightOp, side);
    }
    case 'create-filter': {
      return OT.transCreateFilter(leftOp, rightOp, side);
    }
    case 'update-filter': {
      return OT.transUpdateFilter(leftOp, rightOp, side);
    }
    case 'update-view':
    case 'create-view': {
      return OT.transViewOperation(leftOp, rightOp, side);
    }
    default: {
      // ConfigPatch 为 无冲突OP，不进行转换
      const noConflictOp:
        | ConfigUpdate
        | DeleteImageOperation
        | UpdateImageOperation
        | InsertImageOperation
        | SetSelectionOperation
        | SetScaleOperation
        | RemoveFilterOperation
        | UpdateFreezeOperation
        | RemoveViewOperation = leftOp;
      return side === 'left' ? [noConflictOp] : [rightOp];
    }
  }
};
