import { CreateViewOperation, Operation, UpdateViewOperation } from '@bzl/sheet-js';

export const transViewOperation = (
  leftOp: UpdateViewOperation | CreateViewOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): Operation[] => {
  switch (rightOp.type) {
    case 'create-view':
    case 'update-view': {
      // 判断是否为同一个视图
      if (rightOp.value.id === leftOp.value.id) {
        return side === 'left' ? [leftOp] : [rightOp];
      }
      return [leftOp];
    }
    case 'remove-view': {
      if (rightOp.value.id === leftOp.value.id) {
        return [];
      }
      return [rightOp];
    }
    default:
      return [leftOp];
  }
};
