import { Operation, UpdateFilterOperation } from '@bzl/sheet-js';

export const transUpdateFilter = (
  leftOp: UpdateFilterOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): Operation[] => {
  switch (rightOp.type) {
    case 'create-filter':
    case 'remove-filter': {
      return [];
    }
    case 'update-filter': {
      if (leftOp.col === rightOp.col) {
        return side === 'left' ? [leftOp] : [rightOp];
      }
      return [leftOp];
    }
    case 'insert-col': {
      if (rightOp.at <= leftOp.col) {
        return [
          {
            ...leftOp,
            col: leftOp.col + rightOp.count,
          },
        ];
      }
      return [leftOp];
    }

    case 'remove-col': {
      if (rightOp.at <= leftOp.col && rightOp.at + rightOp.count > leftOp.col) {
        return [];
      } else if (leftOp.col >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            col: leftOp.col - rightOp.count,
          },
        ];
      }
      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
