import { Operation, DeleteAnnotationOperation, InsertAnnotationOperation } from '@bzl/sheet-js';

export const transAnnotation = (
  leftOp: InsertAnnotationOperation | DeleteAnnotationOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): (InsertAnnotationOperation | DeleteAnnotationOperation)[] => {
  const at = leftOp.at;
  switch (rightOp.type) {
    case 'insert-annotation':
    case 'delete-annotation': {
      const conflict = at.col === rightOp.at.col && at.row === rightOp.at.row;
      if (conflict) {
        return side === 'left' ? [leftOp] : [rightOp];
      }
      return [leftOp];
    }
    case 'insert-row': {
      if (at.row >= rightOp.at) {
        return [{ ...leftOp, at: { col: at.col, row: at.row + rightOp.count } }];
      }
      return [leftOp];
    }
    case 'insert-col': {
      if (at.col >= rightOp.at) {
        return [{ ...leftOp, at: { col: at.col + rightOp.count, row: at.row } }];
      }
      return [leftOp];
    }
    case 'remove-row': {
      if (at.row >= rightOp.at && at.row < rightOp.at + rightOp.count) {
        return [];
      }
      if (at.row >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: {
              col: leftOp.at.col,
              row: leftOp.at.row - rightOp.count,
            },
          },
        ];
      }
      return [leftOp];
    }
    case 'remove-col': {
      if (at.col >= rightOp.at && at.col < rightOp.at + rightOp.count) {
        return [];
      }
      if (at.row >= rightOp.at + rightOp.count) {
        return [
          {
            ...leftOp,
            at: {
              row: leftOp.at.row,
              col: leftOp.at.col - rightOp.count,
            },
          },
        ];
      }
      return [leftOp];
    }
    default:
      return [leftOp];
  }
};
