import { RangeMan } from '@boss/h-table';
import { Operation, FillRangeOperation, ScatterRangeOperation } from '@bzl/sheet-js';

export const transFillRange = (
  leftOp: FillRangeOperation,
  rightOp: Operation,
  side: 'right' | 'left',
): Operation[] => {
  switch (rightOp.type) {
    case 'fill-range': {
      // clear 类型互不冲突
      if (side === 'left' || (leftOp.fillBy === 'clear' && rightOp.fillBy === 'clear')) {
        return [leftOp];
      }
      // 不相交 不冲突
      if (!RangeMan.isOverlapping(leftOp.range, rightOp.range)) {
        return [leftOp];
      }

      let needTransform = false;

      // clear 和别的类型都冲突
      if (leftOp.fillBy === 'clear' || rightOp.fillBy === 'clear') {
        needTransform = true;
      } else if (leftOp.fillBy === rightOp.fillBy) {
        if (leftOp.fillBy === 'style') {
          needTransform = Object.keys(leftOp.style!)[0] === Object.keys(rightOp.style!)[0];
        } else if (leftOp.fillBy === 'border') {
          // border 不冲突
        } else if (leftOp.fillBy === 'data') {
          needTransform = true;
        }
      }

      if (needTransform) {
        // 转换切割
        const splitInfo = RangeMan.splitRange(leftOp.range, rightOp.range);
        if (splitInfo) {
          const intersectionSplitRange: FillRangeOperation = {
            ...rightOp,
            range: splitInfo.intersect,
          };
          const leftSplitRange = splitInfo.source.map((r) => ({
            ...leftOp,
            range: r,
          }));
          return leftSplitRange.concat(intersectionSplitRange);
        }
      }
      return [leftOp];
    }
    case 'scatter-range': {
      if (leftOp.fillBy === 'clear' && rightOp.scatterBy !== 'style') {
        return [leftOp];
      }
      if (leftOp.fillBy !== 'clear' && leftOp.fillBy !== rightOp.scatterBy) {
        return [leftOp];
      }
      if (RangeMan.isOverlapping(leftOp.range, rightOp.range)) {
        // 切分 fill range
        const splitInfo = RangeMan.splitRange(leftOp.range, rightOp.range);
        if (splitInfo) {
          return splitInfo.source.map((r) => ({
            ...leftOp,
            range: r,
          }));
        }
      }
      return [leftOp];
    }
    case 'sort': {
      const { range, sortBy, before, after } = rightOp;
      // sortOp的影响区域
      const effectRange = sortBy === 'sheet' ? [0, range[1], Infinity, range[3]] : range;
      if (leftOp.fillBy !== 'data' || RangeMan.isFullOverlapping(leftOp.range, effectRange)) {
        return [leftOp];
      }
      // sort 区域和 fillRange 区域重叠
      if (RangeMan.isOverlapping(leftOp.range, effectRange)) {
        // 需要对 fillRange 区域进行拆分。 并用 scatterRange 来进行描述
        const [startCol, startRow, endCol, endRow] = leftOp.range;
        const scatterRangeOp = {
          type: 'scatter-range',
          range: leftOp.range,
          id: leftOp.id,
          scatterBy: 'data',
          refs: {
            rows: [],
          },
        } as ScatterRangeOperation;
        const newRows: ScatterRangeOperation['refs']['rows'] = [];
        for (let i = startRow; i <= endRow; i++) {
          // 找到排序后索引所在位置
          const afterRowIndex = after.findIndex((r) => r === i);
          const children = [];
          for (let c = startCol; c <= endCol; c++) {
            children.push({
              index: c,
              meta: { ...leftOp.data },
            });
          }
          newRows.push({
            index: afterRowIndex === -1 ? i : before[afterRowIndex],
            children,
          });

          // if (afterRowIndex !== -1) {
          //   // newRows.push({
          //   //   meta: { ...leftOp.data },
          //   //   index: newRowIndex,
          //   // });
          //   const children = []
          //   for(let i = startCol; i<=endCol ; i++){
          //     children.push({
          //       index: i,
          //       meta: { ...leftOp.data },
          //     })
          //   }
          //   newRows.push({
          //     index: before[afterRowIndex],
          //     children
          //   })
          // } else {
          //   // 不在排序范围内，保持索引
          //   newRows.push({
          //     meta: { ...leftOp.data },
          //     index: i,
          //   });
          // }
        }
        newRows.sort((a, b) => a.index - b.index);
        scatterRangeOp.refs.rows = newRows;
        scatterRangeOp.range = [leftOp.range[0], startRow, leftOp.range[2], endRow];
        return [scatterRangeOp];
      }
      return [leftOp];
    }
    case 'insert-col': {
      // 考虑 follow
      const followBottom = rightOp.follow === 'before' && rightOp.at === leftOp.range[2] + 1;
      const followTop = rightOp.follow === 'after' && rightOp.at === leftOp.range[0];
      if (followTop || followBottom) {
        // 扩充 n 行
        const newRange = RangeMan.expand(leftOp.range, [rightOp.count, 0]);
        return [
          {
            ...leftOp,
            range: newRange,
          },
        ];
      }
      const newRange = RangeMan.applyInsertCol(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });

      return [
        {
          ...leftOp,
          range: newRange,
        },
      ];
    }

    case 'remove-col': {
      const newRanges = RangeMan.applyRemoveCol(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      if (newRanges) {
        return [
          {
            ...leftOp,
            range: newRanges,
          },
        ];
      }
      return [];
    }
    case 'insert-row': {
      // 考虑 follow
      const followBottom = rightOp.follow === 'before' && rightOp.at === leftOp.range[3] + 1;
      const followTop = rightOp.follow === 'after' && rightOp.at === leftOp.range[1];
      if (followBottom || followTop) {
        // 扩充 n 行
        const newRange = RangeMan.expand(leftOp.range, [0, rightOp.count]);
        return [
          {
            ...leftOp,
            range: newRange,
          },
        ];
      }
      const newRange = RangeMan.applyInsertRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      return [
        {
          ...leftOp,
          range: newRange,
        },
      ];
    }
    case 'remove-row': {
      const newRanges = RangeMan.applyRemoveRow(leftOp.range, {
        at: rightOp.at,
        count: rightOp.count,
      });
      console.log('fill-range 基于 remove-row转换', newRanges, leftOp.range);
      if (newRanges) {
        return [
          {
            ...leftOp,
            range: newRanges,
          },
        ];
      }
      return [];
    }
    default:
      return [leftOp];
  }
};
